#include "crypto_square.h"

#include <cctype>
#include <cmath>
#include <string>

namespace crypto_square {

std::string cipher(const std::string& plaintext) {
    std::string normalized;

    for (unsigned char character : plaintext) {
        if (std::isalnum(character)) {
            normalized += static_cast<char>(std::tolower(character));
        }
    }

    if (normalized.empty()) {
        return {};
    }

    const std::size_t length = normalized.size();
    std::size_t columns = 1;
    std::size_t rows = 1;

    while (true) {
        for (std::size_t candidate_rows = columns;
             candidate_rows > 0 && candidate_rows + 1 >= columns;
             --candidate_rows) {
            if (candidate_rows * columns >= length) {
                rows = candidate_rows;
                break;
            }
        }

        if (rows * columns >= length && columns >= rows &&
            columns - rows <= 1) {
            break;
        }

        ++columns;
    }

    std::string encoded;

    for (std::size_t column = 0; column < columns; ++column) {
        for (std::size_t row = 0; row < rows; ++row) {
            const std::size_t index = row * columns + column;
            if (index < normalized.size()) {
                encoded += normalized[index];
            } else {
                encoded += ' ';
            }
        }

        if (column + 1 < columns) {
            encoded += ' ';
        }
    }

    return encoded;
}

}  // namespace crypto_square
